sys_variable_value.value:
(function execute(inputs, outputs) {
try { 
        // Instantiates your pre-configured backend outbound REST definition
        var r = new sn_ws.RESTMessageV2('x_1534869_todo_i_0.Todo Lists API', 'Todo Lists API');
        
        // Maps the incoming flow data pills directly to your REST variables
        r.setStringParameterNoEscape('title', inputs.title);
        r.setStringParameterNoEscape('description', inputs.description);
        
        // Transmits the payload out to your endpoint
        var response = r.execute();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();
        
        // Maps the response data back to your action
        outputs.status_code = httpStatus;
        outputs.response_payload = responseBody;
    } catch(ex) {
        outputs.status_code = 500;
        outputs.response_payload = ex.message;
    }
})(inputs, outputs);

